 "Buyer cases": "Casi degli acquirenti",
 "Buyers add it for {amount}, instead of {amount2}.": "Gli acquirenti lo aggiungono a {amount}, invece di {amount2}.",
 "Buyers add it for {amount}.": "Gli acquirenti lo aggiungono a {amount}.",
 "Buyers are asked by email after they buy, on your schedule in Storelib Reviews.": "Agli acquirenti viene chiesto via email dopo l'acquisto, secondo la tua pianificazione in Storelib Reviews.",
 "Buyers ask for a return from their order page, and you approve each one.": "Gli acquirenti chiedono un reso dalla pagina dell'ordine e tu approvi ciascuno.",
 "Buyers can add up to 4 photos. Each one is checked before it is kept.": "Gli acquirenti possono aggiungere fino a 4 foto. Ognuna viene controllata prima di essere salvata.",
 "Buyers can change their review for": "Gli acquirenti possono modificare la recensione per",
 "Buyers can choose it": "Gli acquirenti possono sceglierla",
 "Buyers can collect their order here for free instead of having it shipped.": "Gli acquirenti possono ritirare qui l'ordine gratis invece di farselo spedire.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now instead, turn it off.": "Gli acquirenti non potranno più usarlo. Gli ordini già fatti con questo codice mantengono lo sconto. Per sospenderlo, disattivalo.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now, turn it off instead.": "Gli acquirenti non potranno più usarlo. Gli ordini già fatti con questo codice mantengono lo sconto. Per sospenderlo, disattivalo.",
 "Buyers can still order, and you ship when it's back.": "Gli acquirenti possono ordinare lo stesso e spedisci quando torna disponibile.",
 "Buyers can use it at checkout.": "Gli acquirenti possono usarlo al checkout.",
 "Buyers can't check out a physical product until it has a rate for their address. Add a zone and a rate below.": "Gli acquirenti non possono pagare un prodotto fisico finché non ha una tariffa per il loro indirizzo. Aggiungi una zona e una tariffa qui sotto.",
 "Buyers can't check out on your store yet": "Gli acquirenti non possono ancora pagare nel tuo negozio",
 "Buyers can't check out yet": "Gli acquirenti non possono ancora pagare",
 "Buyers choose the price": "Gli acquirenti scelgono il prezzo",
 "Buyers choose what to pay, from your minimum.": "Gli acquirenti scelgono quanto pagare, dal tuo minimo.",
 "Buyers create an account or log in before checkout. Signed out visitors can still browse.": "Gli acquirenti creano un account o accedono prima del checkout. I visitatori non connessi possono comunque navigare.",
 "Buyers keep their files and their access.": "Gli acquirenti mantengono i file e l'accesso.",
 "Buyers never see it": "Gli acquirenti non lo vedono mai",
 "Buyers only": "Solo acquirenti",
 "Buyers only see it struck through when it is higher than the price.": "Gli acquirenti lo vedono barrato solo se è più alto del prezzo.",
 "Buyers review from their receipt or their library. Storelib asks them a week after they buy on Storelib, and again a week later if they have not.": "Gli acquirenti recensiscono dalla ricevuta o dalla libreria. Storelib lo chiede una settimana dopo l'acquisto su Storelib, e di nuovo una settimana dopo se non l'hanno fatto.",
 "Buyers see it when they choose pickup": "Gli acquirenti lo vedono quando scelgono il ritiro",
 "Buyers see these words on the event page and in their receipt.": "Gli acquirenti vedono questo testo nella pagina dell'evento e nella ricevuta.",
 "Buyers see “Name a fair price”, starting at your suggested amount.": "Gli acquirenti vedono “Indica un prezzo giusto”, a partire dal tuo importo suggerito.",
 "Buyers watch these in their library, and pick up where they left off.": "Gli acquirenti le guardano nella loro libreria e riprendono da dove erano rimasti.",
 "Buyers who asked to hear from you when they paid.": "Acquirenti che al pagamento hanno chiesto di ricevere tue notizie.",
 "Buyers who did not ask for news. They get emails about what they bought, never one you send to your list.": "Acquirenti che non hanno chiesto notizie. Ricevono email su ciò che hanno comprato, mai quelle che invii alla tua lista.",
