 "EN": "EN",
 "Each charge lands here with its invoice.": "Ogni addebito compare qui con la sua fattura.",
 "Each email goes to each person once, however often they trigger it. Someone who unsubscribes gets nothing more.": "Ogni email arriva una volta a ogni persona, per quante volte la attivi. Chi si disiscrive non riceve più nulla.",
 "Each item is priced by its own weight, then added up.": "Ogni articolo è prezzato in base al peso, poi si somma.",
 "Each item pays the price of the step its weight reaches. Two 0.5 {unit} items at a 0 {unit2} step of $3 pay $6.": "Ogni articolo paga il prezzo della fascia raggiunta dal suo peso. Due articoli da 0,5 {unit} in una fascia da 0 {unit2} a 3 $ pagano 6 $.",
 "Each link needs a label and an https:// address.": "Ogni link richiede un'etichetta e un indirizzo https://.",
 "Each new order for this location is sent here": "Ogni nuovo ordine di questa sede viene inviato qui",
 "Each new order is sent to your own system as a signed request. Set the address in Integrations.": "Ogni nuovo ordine viene inviato al tuo sistema come richiesta firmata. Imposta l'indirizzo in Integrazioni.",
 "Each new order with items from here is emailed to this partner with the items and the address. You add their tracking number in Orders when they ship.": "Ogni nuovo ordine con articoli da qui viene inviato via email a questo partner con articoli e indirizzo. Aggiungi il loro numero di tracciamento in Ordini quando spediscono.",
 "Each order is printed and shipped for you.": "Ogni ordine viene stampato e spedito per te.",
 "Each order starts it once. The same order never starts it twice.": "Ogni ordine la avvia una volta. Lo stesso ordine non la avvia mai due volte.",
 "Each question needs an answer.": "Ogni domanda richiede una risposta.",
 "Each rule needs a title.": "Ogni regola richiede un titolo.",
 "Each sale becomes available about {settleDays} days after it is paid. That wait is set by our payment partner for your country and protects against refunds and disputes.": "Ogni vendita diventa disponibile circa {settleDays} giorni dopo il pagamento. L'attesa è stabilita dal nostro partner di pagamento per il tuo paese e protegge da rimborsi e contestazioni.",
 "Each sale becomes available after a short settlement wait set by our payment partner for your country.": "Ogni vendita diventa disponibile dopo una breve attesa stabilita dal nostro partner di pagamento per il tuo paese.",
 "Each variant has its own quantity, in Variants below.": "Ogni variante ha la sua quantità, in Varianti qui sotto.",
