 "Is there a refund policy?": "C'è una politica di rimborso?",
 "It applies only to products in these collections.": "Si applica solo ai prodotti di queste collezioni.",
 "It could not be published. Try again.": "Impossibile pubblicare. Riprova.",
 "It disappears for everyone. Orders and payments are kept. Not possible while members still pay for it.": "Scompare per tutti. Ordini e pagamenti restano. Non è possibile finché ci sono membri paganti.",
 "It goes back to their card in 5 to 10 business days, and your share comes back from your Stripe balance. They get an email.": "Torna sulla carta in 5-10 giorni lavorativi e la tua quota viene ripresa dal saldo Stripe. Riceve un'email.",
 "It goes live at": "Va online su",
 "It has not been saved yet, so it will not be kept.": "Non è ancora stato salvato, quindi non verrà conservato.",
 "It has not been saved yet, so nothing you added will be kept.": "Non è ancora stato salvato, quindi niente di ciò che hai aggiunto verrà conservato.",
 "It has to end after it starts.": "Deve finire dopo l'inizio.",
 "It hides before it shows, so it would never be on the page.": "Si nasconde prima di comparire, quindi non sarebbe mai sulla pagina.",
 "It is a draft. Only you can see it until you publish.": "È una bozza. Solo tu puoi vederla finché non la pubblichi.",
 "It is gone for good, with its photos. To take it off your store and keep it, hide it instead.": "Sparisce per sempre, con le sue foto. Per toglierla dal negozio e tenerla, nascondila.",
 "It is hidden from your product page and its rating now. Storelib reads it and either brings it back or keeps it hidden.": "Ora è nascosta nella pagina prodotto e nella valutazione. Storelib la legge e poi la ripristina o la tiene nascosta.",
 "It is not a Storelib product and is not listed anywhere else.": "Non è un prodotto Storelib e non è elencato altrove.",
 "It is not connected yet, so nothing stops working.": "Non è ancora collegato, quindi non smette di funzionare nulla.",
 "It is off until you turn it on.": "Resta disattivata finché non la attivi.",
 "It is removed from Messages. The email you got about it stays in your inbox, and the sender stays in your contacts.": "Viene rimosso dai Messaggi. L'email ricevuta resta nella tua casella e il mittente resta nei tuoi contatti.",
 "It is removed with its numbers. Anything already sent stays in people's inboxes.": "Viene rimossa con i suoi dati. Ciò che è già stato inviato resta nelle caselle.",
 "It is yours": "È tuo",
 "It opens soon": "Si apre presto",
 "It plays on your page in the YouTube or Vimeo player.": "Viene riprodotto sulla tua pagina nel player di YouTube o Vimeo.",
 "It replaces “{name}” at": "Sostituisce “{name}” su",
 "It shows as cancelled to members, and anyone going hears about it. You can put it back on.": "Ai membri appare come annullato e chi partecipava viene avvisato. Puoi rimetterlo in programma.",
 "It starts as a draft. Add its lessons, then publish it.": "Parte come bozza. Aggiungi le lezioni, poi pubblicalo.",
 "It stops at once for everyone partway through, and its history goes with it.": "Si ferma subito per tutti quelli a metà, e la sua cronologia se ne va con lei.",
