 "It was already sent to your print partner. Cancel it there too.": "È già stato inviato al tuo partner di stampa. Annullalo anche lì.",
 "It was deleted. The email you got about it is still in your inbox.": "È stato eliminato. L'email ricevuta è ancora nella tua casella.",
 "It was used, or it's past the return window.": "È stato usato o il periodo di reso è scaduto.",
 "It's a passport": "È un passaporto",
 "It's here": "È arrivato",
