 "Member status": "Stato del membro",
 "Members": "Membri",
 "Members are told about announcements.": "I membri vengono avvisati degli annunci.",
 "Members can comment on posts here.": "I membri possono commentare i post qui.",
 "Members can read it; nobody can post. Bringing it back makes it a draft.": "I membri possono leggerla; nessuno può pubblicare. Ripristinarla la rende una bozza.",
 "Members can see who else is here.": "I membri possono vedere chi altro c'è.",
 "Members can still read it. Nobody can post or join until you bring it back. Nothing is deleted.": "I membri possono ancora leggerla. Nessuno può pubblicare o iscriversi finché non la ripristini. Non viene eliminato nulla.",
 "Members earn points when their posts and comments get reactions, and climb levels. A leaderboard shows in the community.": "I membri guadagnano punti quando post e commenti ricevono reazioni, e salgono di livello. Nella community c'è una classifica.",
 "Members get these in their library while their membership lasts.": "I membri li trovano nella libreria finché dura l'abbonamento.",
 "Members now": "Membri ora",
 "Members on {name}": "Membri di {name}",
 "Members pay for a tier to join.": "I membri pagano un livello per iscriversi.",
 "Members pay monthly or yearly to join your community.": "I membri pagano al mese o all'anno per entrare nella tua community.",
 "Members pay once, in a checkout inside the community. ": "I membri pagano una volta, con un checkout dentro la community. ",
 "Members pay once, in a checkout inside the community. The meeting link, the address and who else is going open when they have a ticket.": "I membri pagano una volta, con un checkout dentro la community. Link della riunione, indirizzo e chi altro partecipa si vedono con il biglietto.",
 "Members pay through Stripe. You can add a yearly price or more tiers later.": "I membri pagano tramite Stripe. Puoi aggiungere un prezzo annuale o altri livelli in seguito.",
 "Members pay to join, every month, every year or once.": "I membri pagano per iscriversi, ogni mese, ogni anno o una volta.",
 "Members pay you through Stripe. Nobody can join a paid community until payouts are connected.": "I membri ti pagano tramite Stripe. Nessuno può iscriversi a una community a pagamento finché non colleghi i bonifici.",
 "Members pay {amount} once, in a checkout inside the community. ": "I membri pagano {amount} una volta, con un checkout dentro la community. ",
 "Members pay {priceText}.": "I membri pagano {priceText}.",
 "Members paying now, including anyone whose card is being retried. Somebody who cancelled keeps access until their period ends and is not counted.": "Membri che pagano ora, inclusi quelli con la carta in nuovo tentativo. Chi ha annullato mantiene l'accesso fino alla fine del periodo e non viene contato.",
 "Members post": "Pubblicano i membri",
 "Members reach levels by taking part. Below it, they see the program with the level it opens at.": "I membri raggiungono i livelli partecipando. Sotto, vedono il programma con il livello di apertura.",
 "Members see it under Learn.": "I membri lo vedono in Impara.",
 "Members see posts on their membership page. Put the membership on sale in Settings to let people join.": "I membri vedono i post nella pagina dell'abbonamento. Metti in vendita l'abbonamento nelle Impostazioni per far iscrivere le persone.",
 "Members see them before they join and when they post.": "I membri le vedono prima di iscriversi e quando pubblicano.",
 "Members stop seeing it here. The course and its buyers are not touched.": "I membri non lo vedono più qui. Il corso e i suoi acquirenti restano invariati.",
