 "Members stop seeing it, and every open report about it is closed. You can restore it from the Feed.": "I membri non lo vedono più e tutte le segnalazioni aperte vengono chiuse. Puoi ripristinarlo dal Feed.",
 "Members stop seeing it. You can restore it from Removed.": "I membri non lo vedono più. Puoi ripristinarlo da Rimossi.",
