 "Off topic": "Fuori tema",
 "Off, buyers pay your prices and nothing more.": "Disattivato, gli acquirenti pagano i tuoi prezzi e nient'altro.",
 "Off, each order is made in CJ unpaid, and waits until you pay it there. On, it is confirmed and paid from your CJ balance as soon as your buyer pays.": "Disattivato, ogni ordine viene creato in CJ non pagato e attende che lo paghi lì. Attivato, viene confermato e pagato dal saldo CJ appena l'acquirente paga.",
 "Off, each order waits in {name} as a draft until you approve it there, and {name2} charges you only then. On, it is made and charged as soon as it is paid.": "Disattivato, ogni ordine attende in {name} come bozza finché non lo approvi lì, e {name2} ti addebita solo allora. Attivato, viene creato e addebitato appena pagato.",
 "Off, it follows your store setting: {value}{value2}.": "Disattivato, segue l'impostazione del negozio: {value}{value2}.",
 "Off, it stays on your list and on your products, and isn't offered for new ones.": "Disattivato, resta nell'elenco e sui prodotti, ma non viene proposto per quelli nuovi.",
 "Off, the order page has no return button.": "Disattivato, la pagina dell'ordine non ha il pulsante di reso.",
