 "On order emails, so a buyer or a courier can reach you. It also helps your payment provider tell a real shop from a fraudulent one.": "Nelle email degli ordini, così un acquirente o un corriere può contattarti. Aiuta anche il fornitore di pagamenti a distinguere un negozio vero da uno fraudolento.",
