 "What to ask for": "Cosa chiedere",
 "What went wrong?": "Cosa è andato storto?",
 "What would you use it for?": "Per cosa la useresti?",
 "What you hear about": "Di cosa vieni informato",
 "What you pick when you refund an order. It stays on the order's timeline.": "Ciò che scegli quando rimborsi un ordine. Resta nella cronologia dell'ordine.",
 "What you will cover and who it is for": "Di cosa parlerai e a chi è rivolto",
 "What you wrote in this email is replaced.": "Ciò che hai scritto in questa email viene sostituito.",
 "What your buyers get from you, and when. Open one to see it and change its words. Each goes out with your store's name, and a reply comes to your contact email.": "Cosa ricevono gli acquirenti da te, e quando. Aprine una per vederla e modificarne il testo. Ognuna parte con il nome del negozio e le risposte arrivano alla tua email di contatto.",
 "What your completed sales took in over this period, before fees and refunds.": "Quanto hanno incassato le vendite completate in questo periodo, prima di commissioni e rimborsi.",
 "What your website is written in now. It keeps its addresses as they are.": "La lingua in cui è scritto ora il sito. Gli indirizzi restano invariati.",
 "What's Included": "Cosa include",
 "What's included in this variant...": "Cosa include questa variante...",
 "What's it about?": "Di cosa si tratta?",
 "What's the goal here?": "Qual è l'obiettivo?",
 "WhatsApp Group URL": "URL del gruppo WhatsApp",
 "Wheel throwing, from clay to cup": "Tornio, dall'argilla alla tazza",
 "When": "Quando",
 "When a buyer has a problem with an order (it hasn't arrived, it came damaged, they want a refund), they ask from their order page and it lands here and in your email. You answer first; either of you can ask Storelib to step in.": "Quando un acquirente ha un problema con un ordine (non è arrivato, è arrivato danneggiato, vuole un rimborso), lo chiede dalla pagina dell'ordine e arriva qui e nella tua email. Rispondi tu per primo; ognuno dei due può chiedere a Storelib di intervenire.",
 "When a draft was last changed.": "Quando una bozza è stata modificata l'ultima volta.",
 "When a review comes in": "Quando arriva una recensione",
 "When a store's owner invites you, it shows here and you can open it from your own account.": "Quando il proprietario di un negozio ti invita, compare qui e puoi aprirlo dal tuo account.",
 "When buyers can come. Shown at checkout and in the pickup email.": "Quando possono venire gli acquirenti. Mostrato al checkout e nell'email di ritiro.",
 "When members leave they can say why. Their answers show up here.": "Quando i membri se ne vanno possono dire perché. Le risposte compaiono qui.",
 "When members report a post, a comment or somebody, it lands here.": "Quando i membri segnalano un post, un commento o qualcuno, arriva qui.",
 "When somebody writes to you through the contact form on your website, the message shows here and in your email.": "Quando qualcuno ti scrive dal modulo di contatto del tuo sito, il messaggio compare qui e nella tua email.",
 "When someone joins your list": "Quando qualcuno si iscrive alla tua lista",
 "When someone leaves checkout": "Quando qualcuno abbandona il checkout",
 "When the next scheduled email is sent.": "Quando parte la prossima email programmata.",
 "When visitors subscribe, they can download \"": "Quando i visitatori si iscrivono, possono scaricare \"",
 "When will my order arrive?": "Quando arriverà il mio ordine?",
 "When you add a product, ship an order or change a setting, it shows up here.": "Quando aggiungi un prodotto, spedisci un ordine o cambi un'impostazione, compare qui.",
 "Where": "Dove",
 "Where are you based?": "Dove ti trovi?",
 "Where buyers collect their orders. For your default location, it's also where return emails tell buyers to send items.": "Dove gli acquirenti ritirano gli ordini. Per la sede predefinita, è anche l'indirizzo dei resi indicato nelle email.",
 "Where each visit came from, judged by its first page: a search engine, a social app, an email, another website, or typed in directly.": "Da dove è arrivata ogni visita, in base alla prima pagina: un motore di ricerca, un social, un'email, un altro sito o digitata direttamente.",
 "Where it came from": "Da dove proviene",
